from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side

        # Map each boundary point to its clockwise perimeter coordinate in [0, 4*side).
        # Corner precedence: bottom, right, top, left, so each corner is used once.
        coords = []
        for x, y in points:
            if y == 0:
                t = x
            elif x == side:
                t = side + y
            elif y == side:
                t = 3 * side - x
            else:
                t = 4 * side - y
            coords.append(t)

        coords.sort()
        n = len(coords)

        # For k >= 4 the answer is at most side.
        # Also, if k circular gaps are at least d, then k*d <= perimeter.
        hi = min(side, perimeter // k)
        if hi == 0:
            return 0

        # Doubled array with the second copy shifted by one full perimeter.
        arr = coords + [c + perimeter for c in coords]
        m = 2 * n
        steps = range(k - 1)

        def can(d: int) -> bool:
            if d == 0:
                return True

            # nxt[i] = first index j > i with arr[j] - arr[i] >= d.
            nxt = [0] * m
            j = 0
            a = arr
            for i in range(m):
                if j <= i:
                    j = i + 1
                target = a[i] + d
                while j < m and a[j] < target:
                    j += 1
                nxt[i] = j

            # Try every point as the first selected point in circular order.
            nn = n
            for i in range(nn):
                pos = i
                end = i + nn  # same physical point after one full perimeter

                for _ in steps:
                    pos = nxt[pos]
                    if pos >= end:
                        break
                else:
                    # Final wrap-around gap from last selected point back to start.
                    if a[end] - a[pos] >= d:
                        return True

            return False

        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

import sys


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    adj = [[] for _ in range(n + 1)]
    deg = [0] * (n + 1)

    for _ in range(n - 1):
        a = int(next(it))
        b = int(next(it))
        adj[a].append(b)
        adj[b].append(a)
        deg[a] += 1
        deg[b] += 1

    eligible = [False] * (n + 1)
    for i in range(1, n + 1):
        if deg[i] >= 4:
            eligible[i] = True

    parent = [0] * (n + 1)
    dp = [0] * (n + 1)
    max_s = 0

    for root in range(1, n + 1):
        if not eligible[root] or parent[root] != 0:
            continue

        parent[root] = -1
        stack = [root]
        order = []

        while stack:
            v = stack.pop()
            order.append(v)
            for to in adj[v]:
                if eligible[to] and parent[to] == 0:
                    parent[to] = v
                    stack.append(to)

        for v in reversed(order):
            t1 = t2 = t3 = t4 = 0

            for to in adj[v]:
                if parent[to] == v:
                    val = dp[to]
                    if val > t1:
                        t4 = t3
                        t3 = t2
                        t2 = t1
                        t1 = val
                    elif val > t2:
                        t4 = t3
                        t3 = t2
                        t2 = val
                    elif val > t3:
                        t4 = t3
                        t3 = val
                    elif val > t4:
                        t4 = val

            # f[v]: parent of v is selected, so v can take at most 3 child branches.
            dp[v] = 1 + t1 + t2 + t3

            # g[v]: parent of v is not selected, so v can take at most 4 child branches.
            closed = 1 + t1 + t2 + t3 + t4
            if closed > max_s:
                max_s = closed

    if max_s == 0:
        sys.stdout.write("-1\n")
    else:
        sys.stdout.write(str(3 * max_s + 2) + "\n")


