    if direct:
        def dfs(start, rem, cur, A=A, n=N, range=range):
            nonlocal ans
            if rem == 4:
                best = ans
                for i in range(start, n - 3):
                    ai = cur ^ A[i]
                    for j in range(i + 1, n - 2):
                        aij = ai ^ A[j]
                        for k in range(j + 1, n - 1):
                            aijk = aij ^ A[k]
                            for l in range(k + 1, n):
                                v = aijk ^ A[l]
                                if v > best:
                                    best = v
                ans = best
                return

            end = n - rem + 1
            for i in range(start, end):
                dfs(i + 1, rem - 1, cur ^ A[i])
    else:
        t = total

        def dfs(start, rem, cur, A=A, n=N, t=t, range=range):
            nonlocal ans
            if rem == 4:
                best = ans
                base = t ^ cur
                for i in range(start, n - 3):
                    ai = base ^ A[i]
                    for j in range(i + 1, n - 2):
                        aij = ai ^ A[j]
                        for k in range(j + 1, n - 1):
                            aijk = aij ^ A[k]
                            for l in range(k + 1, n):
                                v = aijk ^ A[l]
                                if v > best:
                                    best = v
                ans = best
                return

            end = n - rem + 1
            for i in range(start, end):
                dfs(i + 1, rem - 1, cur ^ A[i])

    dfs(0, M, 0)
    print(ans)


if __name__ == "__main__":
    solve()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        if n == 0:
            return 0
        if n == 1:
            return 1

        bits = [1 if ch == '1' else 0 for ch in s]

        # Zero flips already achieve the original maximum run length.
        max_run = 1
        cur = 1
        for i in range(1, n):
            if bits[i] == bits[i - 1]:
                cur += 1
                if cur > max_run:
                    max_run = cur
            else:
                cur = 1

        if max_run == 1:
            return 1

        INF = numOps + 1

        def feasible(L: int) -> bool:
            # dp0[r]: minimum flips for the processed prefix ending with 0
            #         and current final run length r.
            # dp1[r]: same, ending with 1.
            dp0 = [INF] * (L + 1)
            dp1 = [INF] * (L + 1)

            if bits[0] == 0:
                dp0[1] = 0
                dp1[1] = 1
            else:
                dp0[1] = 1
                dp1[1] = 0

            for i in range(1, n):
                best0 = min(dp0)
                best1 = min(dp1)

                # Costs never decrease, so if every state is already too expensive,
                # no extension can become feasible.
                if best0 > numOps and best1 > numOps:
                    return False

                c0 = bits[i]       # cost to make s[i] become '0'
                c1 = 1 - c0        # cost to make s[i] become '1'

                ndp0 = [INF] * (L + 1)
                ndp1 = [INF] * (L + 1)

                # Switch to the opposite bit: current run length resets to 1.
                if best1 < INF:
                    ndp0[1] = best1 + c0
                if best0 < INF:
                    ndp1[1] = best0 + c1

                # Keep the same bit: extend the current run if it remains <= L.
                for r in range(1, L):
                    v0 = dp0[r]
                    if v0 < INF:
                        ndp0[r + 1] = v0 + c0

                    v1 = dp1[r]
                    if v1 < INF:
                        ndp1[r + 1] = v1 + c1

                dp0, dp1 = ndp0, ndp1

            return min(min(dp0), min(dp1)) <= numOps

        lo, hi = 1, max_run
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

import sys


def main():
    input = sys.stdin.buffer.readline
    line = input()
    if not line:
        return

    n = int(line)
    adj = [[] for _ in range(n)]
    deg = [0] * n

    for _ in range(n - 1):
        u, v = input().split()
        u = int(u) - 1
        v = int(v) - 1
        adj[u].append(v)
        adj[v].append(u)
        deg[u] += 1
        deg[v] += 1

    # deg[v] becomes the capacity of v as a middle vertex:
    # number of possible leaves when its parent/center is excluded.
    deg = [d - 1 for d in deg]

    cap = deg
    adj_local = adj
    best = 0

    for c in range(n):
        adj_c = adj_local[c]
        d = len(adj_c)

        if d == 1:
            a = cap[adj_c[0]]
            if a > 0:
                size = a + 2
                if size > best:
                    best = size

        elif d == 2:
            a = cap[adj_c[0]]
            b = cap[adj_c[1]]
            if a < b:
                a, b = b, a

            if a > 0:
                size = a + 2
                if size > best:
                    best = size

                if b > 0:
                    size = b * 2 + 3
                    if size > best:
                        best = size

        else:
            caps = []
            for nb in adj_c:
                v = cap[nb]
                if v > 0:
                    caps.append(v)

            if caps:
                if len(caps) == 1:
                    size = caps[0] + 2
                    if size > best:
                        best = size
                else:
                    caps.sort(reverse=True)
                    k = 1
                    for v in caps:
                        size = 1 + k * (v + 1)
                        if size > best:
                            best = size
                        k += 1

        if best == n:
            break

    print(n - best)


if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n
        components = n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        # Map each value <= threshold to its original index.
        idx_of = [-1] * (threshold + 1)
        for i, x in enumerate(nums):
            if x <= threshold:
                idx_of[x] = i

        # first[m] = index of the first present divisor of m seen so far.
        first = [-1] * (threshold + 1)

        for d in range(1, threshold + 1):
            idx = idx_of[d]
            if idx == -1:
                continue

            root_idx = find(idx)

            for m in range(d, threshold + 1, d):
                other = first[m]
                if other == -1:
                    first[m] = idx
                else:
                    root_other = find(other)
                    if root_idx != root_other:
                        if size[root_idx] < size[root_other]:
                            parent[root_idx] = root_other
                            size[root_other] += size[root_idx]
                            root_idx = root_other
                        else:
                            parent[root_other] = root_idx
                            size[root_idx] += size[root_other]
                        components -= 1

        return components
